72	
73	    @Column(name = "household_size")
74	    private Integer householdSize;
75	
76	    @Column(name = "membership_level")
77	    private Integer membershipLevel;
78	
79	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
80	    private Set<Pet> pets;
81	
82	    public String getAddress() {
