150	    public void setHouseholdId(String householdId) {
151	        this.householdId = householdId;
152	    }
153	
154	    /**
155	     * The owner's derived identity key, consolidating all duplicate detection into a single value:
156	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two owners are the
157	     * same identity only when their whole key matches, so members of one household (same
158	     * {@code householdId}) with different telephones have distinct keys.
159	     */
160	    @Transient
161	    public String getIdentityKey() {
162	        String tel = this.telephone == null ? "" : this.telephone;
163	        String em = this.email == null ? "" : this.email;
164	        String household = this.householdId == null ? "" : this.householdId;
165	        return tel + "|" + em + "|" + household;
166	    }
167	
168	    public Integer getNamesakeCount() {
169	        return this.namesakeCount;
170	    }
171	
172	    public void setNamesakeCount(Integer namesakeCount) {
